Given a list of tickets, find the itinerary in order using the given list.Note: It may be assumed that the input list of tickets is not cyclic and there is one ticket from every city except the final destination.Examples:Input: "Chennai" -> "Bangalore"            "Bombay" -> "Delhi"             "Goa"    -> "Chennai"             "Delhi"  -> "Goa"Output: Bombay->Delhi, Delhi->Goa, Goa->Chennai, Chennai->BangaloreInput: "New York" -> "Chicago"            "Denver" -> "San Francisco"            "Chicago" -> "Denver"            "San Francisco" -> "Los Angeles"Output: New York -> Chicago, Chicago -> Denver, Denver -> San Francisco, San Francisco -> Los AngelesTable of Content[Expected Approach - 1] - Using Topological Sorting - O(n) Time and O(n) Space[Expected Approach - 2] - Using HashMap - O(n) Time and O(n) Space[Expected Approach - 1] - Using Topological Sorting - O(n) Time and O(n) SpaceThe idea is to use Topological Sorting to sort the cities (nodes). Firstly, store the tickets in a HashMap to create a adjacency list, and create another HashMap to store the visited node. Also, to keep the order of cities, create a stack. Now start from any of the unvisited node and keep pushing the nodes one by one in the stack. At last push all the elements of stack in an array.
            C++

    #include <bits/stdc++.h>
using namespace std;

// Function to perform DFS and topological sorting
void topologicalSortUtil(string v, unordered_map<string, string> &mp, unordered_map<string, int> &visited, stack<string> &st) {
    // Mark the current node as visited
    visited[v] = 1;

    // Recur for adjacent vertex
    if (mp.find(v) != mp.end() && visited[mp[v]] == 0)
        topologicalSortUtil(mp[v], mp, visited, st);

    // Push current vertex onto stack
    if (!v.empty())
        st.push(v);
}

// Function to perform topological sort
vector<string> topologicalSort(unordered_map<string, string> &mp) {
    stack<string> st;
    unordered_map<string, int> visited;

    // Perform DFS for all vertices
    for (auto &i : mp) {
        if (visited[i.first] == 0)
            topologicalSortUtil(i.first, mp, visited, st);
    }

    vector<string> ans;
    while (!st.empty()) {
        ans.push_back(st.top());
        st.pop();
    }

    return ans;
}

// Function to find the itinerary order
vector<vector<string>> findItinerary(vector<vector<string>> &arr) {
    unordered_map<string, string> mp;

    // Map the list of tickets
    for (auto &i : arr) {
        mp[i[0]] = i[1];
    }

    vector<string> res = topologicalSort(mp);
    vector<vector<string>> ans;

    // Create itinerary pairs
    for (size_t i = 0; i < res.size() - 1; i++) {
        ans.push_back({res[i], res[i + 1]});
    }

    return ans;
}

int main() {
    vector<vector<string>> arr = {
        {"Chennai", "Bangalore"},
        {"Bombay", "Delhi"},
        {"Goa", "Chennai"},
        {"Delhi", "Goa"}
    };

    vector<vector<string>> res = findItinerary(arr);

    for (auto &i : res) {
        cout << i[0] << " -> " << i[1] << endl;
    }

    return 0;
}


