[Expected Approach - 2] - Using HashMap - O(n) Time and O(n) SpaceThe idea is to store the list of tickets in a Hashmap and find the starting point of the itinerary. To do so, firstly create a HashMap of given tickets, and also create a reverse HashMap to store the order in reverseNow traverse the first HashMap, and search if key is present in reverse one, the node which is not present is a start point. Now from start point traverse through all other connected  nodes.
            C++

    #include <bits/stdc++.h>
using namespace std;

vector<vector<string>> findItinerary( 
            vector<vector<string>> &arr) {

    map<string, string> dataSet;
    for(auto i:arr) {
        dataSet[i[0]] = i[1];
    }

    map<string, string> reverseMap;
    for(auto i:arr) {
        reverseMap[i[1]] = i[0];
    }

    // Find the starting point of itinerary
    string start;

    for(int i = 0; i<arr.size(); i++) {
        if(reverseMap.count(arr[i][0]) == 0) {
            start = arr[i][0];
            break;
        }
    }

    vector<vector<string>> ans;

    // Once we have starting point, we simple need to go next,
    // next of next using given hash ma
    auto it = dataSet.find(start);
    while (it != dataSet.end()) {
        ans.push_back({it->first, it->second});
        it = dataSet.find(it->second);
    }

    return ans;
}

