    {"Goa", "Chennai"}, {"Delhi", "Goa"}};

    vector<vector<string>> res = findItinerary(arr);
    for(auto i:res) {
        cout<<i[0]<<" -> "<<i[1]<<endl;
    }

    return 0;
}


